start=time.monotonic();p=json.loads((O/'protocol.json').read_text());sp=R/p['source_predictions'];fp=R/p['source_parameters'];assert sha(sp)==p['source_prediction_sha256'] and sha(fp)==p['source_parameter_sha256'];sigma=json.loads(fp.read_text())['sigmas'][p['sigma_key']];assert sigma==p['sigma'];rows=list(csv.DictReader(sp.open()));assert len(rows)==4567 and all(r['role']=='calibration' for r in rows);ids=sorted({r['cell_id'] for r in rows});assert len(ids)==10;pc=[];examples=[];n=0;logSmin=0.;residmax=0.;condmin=float('inf');condzero=0;expired=0
