 for j in [0,len(rr)//2,len(rr)-1]:examples.append(dict(cell_id=cid,origin=int(t[j]),mu100=mu,sigma=sigma,true_RUL=float(y[j]),elapsed=int(d[j]),log_survival_of_elapsed=float(logS[j]),fixed_RUL=float(fixed[j]),survival_conditioned_RUL=float(cond[j]),dynamic_RUL=float(dynamic[j])))
